def solve_min_cost_efficient(n):
    import math
    T = n * (n - 1) // 2
    x = [0] * (T + 1)
    for t in range(1, T + 1):
        f_t = math.ceil((1 + (1 + 8 * t)**0.5) / 2)
        x[t] = max(f_t, n - 2 * (T - t))
    for t in range(2, T + 1):
        x[t] = max(x[t], x[t-1])
    for t in range(T, 1, -1):
        x[t-1] = max(x[t-1], x[t] - 2)
    sum_x = sum(x)
    y = [0] * (T + 1)
    for t in range(1, T + 1):
        g_t = math.ceil((1 + (1 + 8 * (T - t + 1))**0.5) / 2)
        y[t] = max(g_t, n - 2 * (t - 1))
    for t in range(2, T + 1):
        y[t] = max(y[t], y[t-1])
    for t in range(T, 1, -1):
        y[t-1] = max(y[t-1], y[t] - 2)
    sum_y = sum(y)
    return sum_x + sum_y - n * T

